import os
libp=P+'lib.py'
stamp_fn='''

def find_marker_figure(grid, bg=0):
    """The bounding-box cell pattern of the non-background marker color (the rarest color's cells)."""
    from collections import Counter
    cnt = Counter(v for row in grid for v in row)
    marker = min((v for v in cnt if v != bg), key=lambda v: cnt[v])
    pts = [(i, j) for i, row in enumerate(grid) for j, v in enumerate(row) if v == marker]
    r0 = min(p[0] for p in pts); c0 = min(p[1] for p in pts)
    return marker, sorted((p[0] - r0, p[1] - c0) for p in pts)

def stamp_figure_on_holes(grid, marker=None, figure=None, bg=0):
    """Stamp the marker figure (its relative pattern) onto every spot whose cells are all background holes, recoloring them the marker color."""
    if marker is None or figure is None:
        marker, figure = find_marker_figure(grid, bg)
    h = max(p[0] for p in figure) + 1; w = max(p[1] for p in figure) + 1
    out = [row[:] for row in grid]
    for r in range(len(grid) - h + 1):
        for c in range(len(grid[0]) - w + 1):
            if all(grid[r + a][c + b] == bg for a, b in figure):
                for a, b in figure:
                    out[r + a][c + b] = marker
    return out
